package main
import "testing"
func TestWordCount(t *testing.T) {
  got := WordCount("a b a c b a")
  want := map[string]int{"a":3, "b":2, "c":1}
  for k, v := range want {
    if got[k] != v { t.Fatalf("%s: got %d want %d", k, got[k], v) }
  }
  if len(got) != len(want) { t.Fatalf("len got %d want %d", len(got), len(want)) }
}
